using OpenGameSave;
var root = Path.Combine(Path.GetTempPath(), "opengamesave-" + Guid.NewGuid().ToString("N")); var save = Path.Combine(root, "save"); var library = Path.Combine(root, "library"); Directory.CreateDirectory(save); File.WriteAllText(Path.Combine(save, "slot.dat"), "progress"); var snapshot = SaveEngine.CreateSnapshot(new GameProfile("TestGame", null, save), library); var snapRoot = Path.Combine(library, "TestGame", snapshot.Id); if (!SaveEngine.Verify(snapRoot)) throw new Exception("Fresh snapshot did not verify."); var restore = Path.Combine(root, "restore"); if (SaveEngine.Restore(snapRoot, restore) != 1 || File.ReadAllText(Path.Combine(restore, "slot.dat")) != "progress") throw new Exception("Restore failed."); File.AppendAllText(Path.Combine(snapRoot, "slot.dat"), "tampered"); if (SaveEngine.Verify(snapRoot)) throw new Exception("Tampered snapshot verified."); Directory.Delete(root, true); Console.WriteLine("PASS: save snapshot, verified restore, and tamper detection");
